{
  "findings": [
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket ACL is set to 'log-delivery-write' which may allow unintended access or is deprecated in favor of Bucket Owner Enforcement",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "While 'log-delivery-write' is specific for log delivery, using legacy ACLs is discouraged. More importantly, if this bucket is intended to receive logs from other services, it should rely on bucket policies and S3 Object Ownership (BucketOwnerEnforced) rather than ACLs to prevent cross-account data leakage or misconfiguration risks associated with ACL-based permissions."
    },
    {
      "check_id": "CKV_AWS_20",
      "title": "S3 Bucket does not have a public access block configured",
      "resource": "aws_s3_bucket.logs",
      "severity": "HIGH",
      "explanation": "The resource lacks an `aws_s3_bucket_public_access_block` configuration. Without explicitly blocking public access, the bucket could be exposed to the internet if ACLs or bucket policies are misconfigured elsewhere, violating the principle of least privilege and defense-in-depth."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "private"
  versioning {
    enabled = true
  }
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}",
  "fix_summary": "Changed the S3 bucket ACL from 'log-delivery-write' to 'private' to adhere to modern security best practices that favor bucket policies over ACLs. Added an `aws_s3_bucket_public_access_block` resource to explicitly deny all public access to the bucket, ensuring it cannot be accidentally exposed to the internet."
}
